  if (active && active.tagName === 'INPUT' && !active.disabled) {
    if (e.key === 'Enter' && keyMap['__inputEnter__']) { keyMap['__inputEnter__'](); }
    if (e.key === 'Escape' && keyMap['__unknown__']) { e.preventDefault(); keyMap['__unknown__'](); }
    return;
  }
  if (e.key === 'Escape' && keyMap['__unknown__']) { e.preventDefault(); keyMap['__unknown__'](); return; }
  if (e.key.toLowerCase() === 'a' && currentSpeechText) { e.preventDefault(); speakWord(currentSpeechText); return; }
