function rate(qMode, en, tier) {
  let box, due, masteredFlag = false;
  if (tier === 'sure') { box = 5; masteredFlag = true; due = Date.now() + MASTER_DUE; }
  else if (tier === 'vague') { box = 1; due = Date.now(); }
  else { box = 0; due = Date.now(); }
  ensureNamespace(qMode)[en] = {box, due, mastered: masteredFlag, tier};
  recordAttempt(qMode, en, tier, questionStartedAt ? Date.now() - questionStartedAt : null);
  questionStartedAt = 0;
  saveState();
  sessionStats[tier]++;
}

// manual move from list screens (mastered <-> review) - same state shape as rate(), no session stats involved
function manualSetTier(qMode, en, tier) {
  let box, due, masteredFlag = false;
  if (tier === 'sure') { box = 5; masteredFlag = true; due = Date.now() + MASTER_DUE; }
  else { box = 0; due = Date.now(); }
  ensureNamespace(qMode)[en] = {box, due, mastered: masteredFlag, tier};
  saveState();
}

