// ---------- cloud sync via jsonbin.io (compact format) ----------
const CLOUD_KEY = 'toefl-vocab-cloud-config';
const CLOUD_FORMAT_VERSION = 1;

/*
  중요:
  - localStorage의 srsState 구조는 기존 그대로 유지한다.
  - JSONBin으로 보낼 때만 압축한다.
  - 현재 앱에서 상태는 사실상 tier 하나로 복원 가능하다.

  sure  -> box 5 / mastered true
  vague -> box 1 / mastered false
  guess -> box 0 / mastered false

  단어명 자체도 저장하지 않고 WORDS 배열의 index를 base36으로 저장한다.

  예:
  exploit(index 0), sure -> "0s"
  prominent(index 3), guess -> "3g"

  따라서 기존 JSON보다 매우 작아진다.
*/

const TIER_TO_CODE = {
  sure: 's',
  vague: 'v',
  guess: 'g'
};

const CODE_TO_TIER = {
  s: 'sure',
  v: 'vague',
  g: 'guess'
};

function loadCloudConfig() {
  try {
    return JSON.parse(localStorage.getItem(CLOUD_KEY)) || {
      apiKey: '',
      binId: ''
    };
  } catch (e) {
    return {
      apiKey: '',
      binId: ''
    };
  }
}

function saveCloudConfig(cfg) {
  try {
    localStorage.setItem(CLOUD_KEY, JSON.stringify(cfg));
  } catch (e) {}
}

// metadata는 학습 기록이 있는 단어만 index 기반으로 저장해 JSONBin 크기를 줄인다.
function packWordMeta() {
  const entries = [];
  WORDS.forEach((word, index) => {
    const m = wordMeta[word.en];
    if (!m) return;
    const a = ['flash','quiz_ko','quiz_en','typed'].map(k => Number(m.attempts && m.attempts[k] || 0));
    const f = ['flash','quiz_ko','quiz_en','typed'].map(k => Number(m.failures && m.failures[k] || 0));
    const r = ['flash','quiz_ko','quiz_en','typed'].map(k => Math.max(0, Number(m.lastResponseMs && m.lastResponseMs[k] || 0)));
    const dm=m.dailyLearning||{}, sr=m.spacedRecall||{};
    const toDay=d=>d?Math.max(0,Math.floor(new Date(d+'T00:00:00').getTime()/DAY)).toString(36):'';
    const dates=list=>(Array.isArray(list)?list:[]).map(toDay).filter(Boolean).join('_');
    const daily=[toDay(dm.date),Number(dm.fullRecallFailures||0).toString(36),Number(dm.fullRecallSuccesses||0).toString(36),Number(dm.quickRepairs||0).toString(36),dm.exposureDone?'1':'',dm.recognitionPassed?'1':'',Number(dm.unaidedSuccesses||0).toString(36),Number(dm.unaidedFailures||0).toString(36),Number(dm.repairLevel||0).toString(36),dm.firstExposureAt?Math.floor(dm.firstExposureAt/60000).toString(36):'',dm.lastQualifiedRecallAt?Math.floor(dm.lastQualifiedRecallAt/60000).toString(36):'',dm.lastQualifiedRecallIndex!=null?Number(dm.lastQualifiedRecallIndex).toString(36):'',dm.todayMastered?'1':'',dm.finalPassed?'1':''].join('~');
    const spaced=[dates(sr.successfulDates),dates(sr.failureDates),Number(sr.level||0).toString(36),sr.lastSuccessfulRecallAt?Math.floor(sr.lastSuccessfulRecallAt/DAY).toString(36):'',sr.nextReviewAt?Math.floor(sr.nextReviewAt/DAY).toString(36):'',sr.tomorrowPriority?'1':''].join('~');
    const hook=m.memoryHook?btoa(unescape(encodeURIComponent(String(m.memoryHook).slice(0,80)))).replace(/=/g,''):'';
    if (!a.some(Boolean) && !f.some(Boolean) && !m.hard && !hook && !sr.nextReviewAt && !dates(sr.successfulDates) && !dates(sr.failureDates)) return;
    entries.push(index.toString(36) + '|' + a.map(n => n.toString(36)).join(',') + '|' + f.map(n => n.toString(36)).join(',') + '|' + r.map(n => n.toString(36)).join(',') + '|' + (m.hard ? '1' : '0') + '|' + Number(m.typedSureStreak || 0).toString(36) + '|' + (m.hardManual?'1':'') + '|' + (m.hardAuto?'1':'') + '|' + daily + '|' + spaced + '|' + hook);
  });
  return entries.join('.');
}
function unpackWordMeta(packed) {
  const restored = {};
  if (typeof packed !== 'string') return packed && typeof packed === 'object' ? packed : restored;
  packed.split('.').forEach(entry => {
    const parts = entry.split('|'); if (parts.length < 6) return;
    const word = WORDS[parseInt(parts[0], 36)]; if (!word) return;
    const nums = part => (part || '').split(',').map(v => parseInt(v || '0', 36) || 0);
    const a = nums(parts[1]), f = nums(parts[2]), r = nums(parts[3]);
    const fromDay=v=>{const n=parseInt(v||'',36);return Number.isFinite(n)&&n?new Date(n*DAY).toISOString().slice(0,10):'';};
    const dl=(parts[8]||'').split('~'), sr=(parts[9]||'').split('~');
    const dateList=v=>(v||'').split('_').map(fromDay).filter(Boolean);
    let hook=''; try { if(parts[10]) hook=decodeURIComponent(escape(atob(parts[10]+'='.repeat((4-parts[10].length%4)%4)))); } catch(e) {}
    restored[word.en] = {attempts:{flash:a[0]||0,quiz_ko:a[1]||0,quiz_en:a[2]||0,typed:a[3]||0}, failures:{flash:f[0]||0,quiz_ko:f[1]||0,quiz_en:f[2]||0,typed:f[3]||0}, lastResponseMs:{flash:r[0]||null,quiz_ko:r[1]||null,quiz_en:r[2]||null,typed:r[3]||null}, hard:parts[4] === '1', hardManual:parts.length>6?parts[6]==='1':parts[4]==='1', hardAuto:parts[7]==='1', typedSureStreak:parseInt(parts[5],36)||0, lastAttemptAt:null, memoryHook:hook, dailyLearning:{date:fromDay(dl[0]),fullRecallFailures:parseInt(dl[1]||'0',36)||0,fullRecallSuccesses:parseInt(dl[2]||'0',36)||0,quickRepairs:parseInt(dl[3]||'0',36)||0,exposureDone:dl[4]==='1',recognitionPassed:dl[5]==='1',unaidedSuccesses:parseInt(dl[6]||'0',36)||0,unaidedFailures:parseInt(dl[7]||'0',36)||0,repairLevel:parseInt(dl[8]||'0',36)||0,firstExposureAt:dl[9]?(parseInt(dl[9],36)||0)*60000:null,lastQualifiedRecallAt:dl[10]?(parseInt(dl[10],36)||0)*60000:null,lastQualifiedRecallIndex:dl[11]!==''?(parseInt(dl[11],36)||0):null,todayMastered:dl[12]==='1',finalPassed:dl[13]==='1'}, spacedRecall:{successfulDates:dateList(sr[0]),failureDates:dateList(sr[1]),level:parseInt(sr[2]||'0',36)||0,lastSuccessfulRecallAt:sr[3]?(parseInt(sr[3],36)||0)*DAY:null,nextReviewAt:sr[4]?(parseInt(sr[4],36)||0)*DAY:null,tomorrowPriority:sr[5]==='1'}};
  });
  return restored;
}


// ----------------------------------------------------
// 클라우드용 압축
// ----------------------------------------------------

function packCloudState(state = srsState) {
  const packedModes = QUIZ_MODES.map(qMode => {
    const namespace = state[qMode] || {};
    const packed = [];

    WORDS.forEach((word, index) => {
      const s = namespace[word.en];
      if (!s) return;

      let tier = s.tier;

      // 예전 데이터에서 tier가 없더라도 최대한 복구
      if (!tier) {
        if (s.mastered || s.box >= 5) {
          tier = 'sure';
        } else if (s.box === 1) {
          tier = 'vague';
        } else {
          tier = 'guess';
        }
      }

      const code = TIER_TO_CODE[tier];
      if (!code) return;

      // index를 base36으로 바꿔 크기를 더 줄임
      packed.push(index.toString(36) + code);
    });

    return packed.join('.');
  });

  return {
    v: CLOUD_FORMAT_VERSION,
    q: packedModes,
    m: packWordMeta(),
    a: audioSetting === 'always' ? 'a' : audioSetting === 'off' ? 'o' : 'l'
  };
}


// ----------------------------------------------------
// 압축된 클라우드 데이터 → 기존 srsState 복원
// ----------------------------------------------------

function unpackCloudState(record) {

  // 새 압축 포맷
  if (
    record &&
    record.v === CLOUD_FORMAT_VERSION &&
    Array.isArray(record.q)
  ) {
    const restored = {};

    QUIZ_MODES.forEach((qMode, modeIndex) => {
      restored[qMode] = {};

      const packedString = record.q[modeIndex] || '';
      if (!packedString) return;

      const entries = packedString.split('.');

      entries.forEach(token => {
        if (!token || token.length < 2) return;

        const tierCode = token.slice(-1);
        const indexPart = token.slice(0, -1);

        const wordIndex = parseInt(indexPart, 36);
        const tier = CODE_TO_TIER[tierCode];

        if (
          !Number.isInteger(wordIndex) ||
          !WORDS[wordIndex] ||
          !tier
        ) {
          return;
        }

        const word = WORDS[wordIndex];

        let box;
        let due;
        let mastered = false;

        if (tier === 'sure') {
          box = 5;
          mastered = true;
          due = Date.now() + MASTER_DUE;
        } else if (tier === 'vague') {
          box = 1;
          due = Date.now();
        } else {
          box = 0;
          due = Date.now();
        }

        restored[qMode][word.en] = {
          box,
          due,
          mastered,
          tier
        };
      });
    });

    restored.__wordMeta = unpackWordMeta(record.m || {});
    restored.__audioSetting = record.a === 'a' ? 'always' : record.a === 'o' ? 'off' : 'learning';
    return restored;
  }


  /*
    구버전 호환

    지금까지 JSONBin에 저장했던 데이터는
    srsState 자체가 그대로 들어가 있으므로
    새 포맷이 아니면 그냥 기존 데이터로 취급한다.

    즉 예전에 성공적으로 업로드한 Bin도 다운로드 가능.
  */
  return record || {};
}


// ----------------------------------------------------
// 실제 전송 크기
// ----------------------------------------------------

function getCloudPayload() {
  return packCloudState(srsState);
}

async function gzipCloudPayload(payload) {
  if (typeof CompressionStream === 'undefined') return payload;
  const bytes = new TextEncoder().encode(JSON.stringify(payload));
  const stream = new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip'));
  const compressed = new Uint8Array(await new Response(stream).arrayBuffer());
  let binary=''; for(let i=0;i<compressed.length;i+=8192) binary+=String.fromCharCode(...compressed.subarray(i,i+8192));
  return {v:2,z:btoa(binary)};
}
async function gunzipCloudPayload(record) {
  if (!record || record.v !== 2 || typeof record.z !== 'string') return record;
  if (typeof DecompressionStream === 'undefined') throw new Error('이 브라우저는 압축 백업 복원을 지원하지 않습니다. 최신 Safari/Chrome을 사용하세요.');
  const binary=atob(record.z), bytes=new Uint8Array(binary.length); for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
  const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
  return JSON.parse(await new Response(stream).text());
}
async function getCloudUploadPayload() {
  const payload=await gzipCloudPayload(getCloudPayload());
  assertCloudPayloadLimit(payload);
  return payload;
}

function getCloudPayloadSize() {
  const json = JSON.stringify(getCloudPayload());
  return new Blob([json]).size;
}
function assertCloudPayloadLimit(payload) {
  const size = new Blob([JSON.stringify(payload)]).size;
  if (size > 100 * 1024) throw new Error('클라우드 백업 데이터가 100KB를 초과했습니다 (' + formatBytes(size) + ').');
  return size;
}

function formatBytes(bytes) {
  if (bytes < 1024) {
    return bytes + ' B';
  }

  return (bytes / 1024).toFixed(1) + ' KB';
}


// ----------------------------------------------------
// JSONBin 오류 내용 표시
// ----------------------------------------------------

async function makeJsonBinError(res) {
  let detail = '';

  try {
    const text = await res.text();

    if (text) {
      try {
        const parsed = JSON.parse(text);
        detail =
          parsed.message ||
          parsed.error ||
          text;
      } catch (e) {
        detail = text;
      }
    }
  } catch (e) {}

  if (detail) {
    return new Error(
      'HTTP ' + res.status + ' — ' + detail
    );
  }

  return new Error(
    'HTTP ' + res.status
  );
}


// ----------------------------------------------------
// 새 Bin 생성
// ----------------------------------------------------

async function createBin(apiKey) {

  const payload = await getCloudUploadPayload();

  const res = await fetch(
    'https://api.jsonbin.io/v3/b',
    {
      method: 'POST',

      headers: {
        'Content-Type': 'application/json',
        'X-Master-Key': apiKey,
        'X-Bin-Private': 'true',
        'X-Bin-Name': 'toefl-vocab-srs'
      },

      body: JSON.stringify(payload)
    }
  );

  if (!res.ok) {
    throw await makeJsonBinError(res);
  }

  const data = await res.json();

  return data.metadata.id;
}


// ----------------------------------------------------
// 업로드
// ----------------------------------------------------

async function uploadToBin(apiKey, binId) {

  const payload = await getCloudUploadPayload();

  const res = await fetch(
    'https://api.jsonbin.io/v3/b/' + binId,
    {
      method: 'PUT',

      headers: {
        'Content-Type': 'application/json',
        'X-Master-Key': apiKey
      },

      body: JSON.stringify(payload)
    }
  );

  if (!res.ok) {
    throw await makeJsonBinError(res);
  }

  return await res.json();
}


// ----------------------------------------------------
// 다운로드
// ----------------------------------------------------

async function downloadFromBin(apiKey, binId) {

  const res = await fetch(
    'https://api.jsonbin.io/v3/b/' +
      binId +
      '/latest',
    {
      headers: {
        'X-Master-Key': apiKey
      }
    }
  );

  if (!res.ok) {
    throw await makeJsonBinError(res);
  }

  const data = await res.json();

  // 새 압축 포맷이든 기존 포맷이든 자동 처리
  return unpackCloudState(await gunzipCloudPayload(data.record));
}


