function renderDaySelector(wrap) {
  const heading = el('div', 'display:flex;justify-content:space-between;align-items:center;gap:8px;margin:16px 0 8px');
  heading.appendChild(el('div', 'font-size:13px;color:#666', `Day \uc120\ud0dd \u00b7 ${selectedDayLabel()}`));
  const allBtn = el('button', `padding:7px 12px;border-radius:999px;border:1px solid #ccc;cursor:pointer;font-size:12px;background:${selectedDays.size===ALL_DAYS.length?'#0F6E56':'#f5f5f5'};color:${selectedDays.size===ALL_DAYS.length?'#fff':'#111'}`, '\uc804\uccb4 Day');
  allBtn.onclick = () => { selectedDays = new Set(ALL_DAYS); saveSelectedDays(); renderHome(); };
  heading.appendChild(allBtn);
  wrap.appendChild(heading);

  wrap.appendChild(el('div', 'font-size:11px;color:#999;margin-bottom:8px', '\uc804\uccb4 \uc120\ud0dd \uc0c1\ud0dc\uc5d0\uc11c Day\ub97c \ub204\ub974\uba74 \ud574\ub2f9 Day\ub9cc \ub0a8\uace0, \uadf8 \ub2e4\uc74c\ubd80\ud130\ub294 \uc5ec\ub7ec Day\ub97c \ucd94\uac00\ub85c \uace0\ub97c \uc218 \uc788\uc5b4\uc694.'));
  const grid = el('div', 'display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin-bottom:14px');
  ALL_DAYS.forEach(day => {
    const active = selectedDays.has(day);
    const count = WORDS.filter(word => word.day === day).length;
    const button = el('button', `padding:8px 2px;border-radius:7px;border:1px solid ${active?'#0F6E56':'#ddd'};cursor:pointer;font-size:12px;background:${active?'#e8f5ee':'#f5f5f5'};color:${active?'#0F6E56':'#777'};font-weight:${active?'600':'400'}`, `Day ${day}<br><span style="font-size:10px;opacity:0.75">${count}\uac1c</span>`);
    button.setAttribute('aria-pressed', active ? 'true' : 'false');
    button.onclick = () => {
      if (selectedDays.size === ALL_DAYS.length) selectedDays = new Set([day]);
      else if (selectedDays.has(day)) {
        if (selectedDays.size === 1) return;
        selectedDays.delete(day);
      } else selectedDays.add(day);
      saveSelectedDays();
      renderHome();
    };
    grid.appendChild(button);
  });
  wrap.appendChild(grid);
}

